class FvInspection extends DataClass implements Insertable<FvInspection> {
  /// Generated on the device. Also the server-side idempotency key, so a
  /// retried upload updates rather than duplicates.
  final String clientUuid;
  final String status;
  final DateTime inspectedAt;
  final int? inspectionPointId;
  final String clientName;
  final String clientAddress;
  final String clientContactPerson;
  final String clientContactNumber;
  final String marketPlace;
  final int commodityId;
  final int? cultivarId;
  final int? countryId;
  final String consignmentDescription;
  final String containerNumbers;
