  final String grnVoucher;
  final String billOfEntry;
  final double? sampleWeightKg;
  final double? markedContainerWeightKg;
  final int? markedGradeId;
  final double? brixReading;
  final int? determinedGradeId;
  final bool gradeOverridden;
  final String overrideReason;
  final String remarks;
  final double? latitude;
  final double? longitude;

  /// Comma-separated requirement ids that failed.
  final String failedRequirementIds;
  final bool isUploaded;
  final DateTime updatedAt;
  const FvInspection(
      {required this.clientUuid,
      required this.status,
      required this.inspectedAt,
      this.inspectionPointId,
