      required this.grnVoucher,
      required this.billOfEntry,
      this.sampleWeightKg,
      this.markedContainerWeightKg,
      this.markedGradeId,
      this.brixReading,
      this.determinedGradeId,
      required this.gradeOverridden,
      required this.overrideReason,
      required this.remarks,
