      map['facility_type_id'] = Variable<int>(facilityTypeId);
    }
    map['facility_address'] = Variable<String>(facilityAddress);
    map['facility_phone'] = Variable<String>(facilityPhone);
    if (!nullToAbsent || reasonId != null) {
      map['reason_id'] = Variable<int>(reasonId);
    }
    map['client_name'] = Variable<String>(clientName);
    map['client_address'] = Variable<String>(clientAddress);
    map['client_contact_person'] = Variable<String>(clientContactPerson);
    map['client_contact_number'] = Variable<String>(clientContactNumber);
    map['client_email'] = Variable<String>(clientEmail);
    map['representative_name'] = Variable<String>(representativeName);
    map['manager_name'] = Variable<String>(managerName);
    map['manager_email'] = Variable<String>(managerEmail);
    map['producer_supplier'] = Variable<String>(producerSupplier);
    map['batch_number'] = Variable<String>(batchNumber);
    if (!nullToAbsent || bestBefore != null) {
      map['best_before'] = Variable<DateTime>(bestBefore);
    }
    if (!nullToAbsent || traySizeId != null) {
      map['tray_size_id'] = Variable<int>(traySizeId);
    }
    if (!nullToAbsent || declaredSizeId != null) {
      map['declared_size_id'] = Variable<int>(declaredSizeId);
    }
    if (!nullToAbsent || declaredGradeId != null) {
      map['declared_grade_id'] = Variable<int>(declaredGradeId);
    }
    if (!nullToAbsent || sampleSize != null) {
      map['sample_size'] = Variable<int>(sampleSize);
    }
    map['pasteurised_present'] = Variable<bool>(pasteurisedPresent);
    map['haugh_not_required'] = Variable<bool>(haughNotRequired);
    map['weighing_not_required'] = Variable<bool>(weighingNotRequired);
    map['outer_labelling_available'] = Variable<bool>(outerLabellingAvailable);
    map['label_checklist_complete'] = Variable<bool>(labelChecklistComplete);
    if (!nullToAbsent || determinedGradeId != null) {
      map['determined_grade_id'] = Variable<int>(determinedGradeId);
    }
    map['grade_overridden'] = Variable<bool>(gradeOverridden);
    map['override_reason'] = Variable<String>(overrideReason);
    map['general_comments'] = Variable<String>(generalComments);
    map['non_conformance_comments'] = Variable<String>(nonConformanceComments);
    map['failed_requirement_ids'] = Variable<String>(failedRequirementIds);
    map['restricted_particular_ids'] =
        Variable<String>(restrictedParticularIds);
    map['restricted_particulars_text'] =
        Variable<String>(restrictedParticularsText);
    if (!nullToAbsent || latitude != null) {
      map['latitude'] = Variable<double>(latitude);
    }
    if (!nullToAbsent || longitude != null) {
      map['longitude'] = Variable<double>(longitude);
    }
    map['seizure_decision'] = Variable<String>(seizureDecision);
    map['eggs_expression_absent'] = Variable<bool>(eggsExpressionAbsent);
    map['best_before_absent'] = Variable<bool>(bestBeforeAbsent);
    map['is_uploaded'] = Variable<bool>(isUploaded);
    map['updated_at'] = Variable<DateTime>(updatedAt);
    if (!nullToAbsent || inspectorUsername != null) {
      map['inspector_username'] = Variable<String>(inspectorUsername);
    }
    return map;
  }

  EggInspectionsCompanion toCompanion(bool nullToAbsent) {
    return EggInspectionsCompanion(
      clientUuid: Value(clientUuid),
      visitUuid: Value(visitUuid),
      status: Value(status),
      inspectedAt: Value(inspectedAt),
      facilityName: Value(facilityName),
      facilityTypeId: facilityTypeId == null && nullToAbsent
          ? const Value.absent()
