class StoreVisit extends DataClass implements Insertable<StoreVisit> {
  final String uuid;
  final String facilityName;
  final String facilityAddress;
  final String facilityPhone;
  final String contactPerson;
  final String contactEmail;
  final String representative;
  final String managerName;
  final String managerEmail;

  /// Anyone else who should receive the documents for this visit — head
  /// office, a group quality manager. The original asks for these on every
  /// commodity form ("Email address #1 / #2"); a visit is one errand to one
  /// site, so they are asked once here and carried onto each record.
  final String additionalEmail1;
  final String additionalEmail2;

  /// A third, offered only once the first two are used — some groups copy
  /// head office as well as the store and its quality manager.
  final String additionalEmail3;

  /// What the invoice is billed on, for the whole trip.
  ///
  /// One journey to one facility, so it is asked once at the door rather
  /// than on every inspection captured there. It used to live only on the
  /// raw record: two raw inspections in a visit asked for it twice and the
  /// invoice kept whichever it read first.
  final double? distanceTravelledKm;
  final String inspectorUsername;

  /// How many of each commodity the inspector planned for this visit —
  /// "2 poultry and 2 raw" — set up front, so the flow can walk them
  /// through the plan commodity by commodity.
  final int plannedEggs;
  final int plannedPoultry;
  final int plannedLabels;
  final int plannedRaw;
  final int plannedPmp;

  /// The commodities in the order the inspector planned them, comma
  /// separated — "rawrmp,egg".
  ///
  /// The flow used to walk a fixed list, so it always opened eggs first
  /// however the plan was set. An inspector who is doing the raw counter
  /// first and the eggs after was made to work in the app's order rather
  /// than the store's. The order the counters were raised in is the order
  /// the work is actually done in, so it is what the plan is walked in.
  final String planOrder;

  /// Answered at the door: is this visit an occurrence report? The report
  /// itself lives on APS; the handset only carries the answer.
  final bool isOccurrenceReport;

  /// Chosen once at the door for the whole group, by name, so each
  /// commodity's form can find its own row for it.
  final String facilityType;

  /// Why the inspector is here, answered once at the door for the whole
  /// group, by name — the commodity lists spell it differently ("Follow Up"
  /// against "Follow-up Inspection"), so each form matches its own row.
  /// Before this the same question was put again on every inspection inside
  /// the visit.
  final String inspectionReason;

  /// The occurrence report as written at the door: when the inspector was
  /// there, the premises' registration code, and what happened. The
  /// photographs live in [VisitOccurrencePhotos].
  final String occurrenceTimeOfVisit;
  final String occurrenceRegistrationCode;
  final String occurrenceDescription;

  /// The closing signatures, kept on the visit itself so a visit with no
  /// inspections (an occurrence report) still has them for its document.
  final String managerSignaturePath;
  final String inspectorSignaturePath;
  final DateTime startedAt;

  /// Set when the closing signatures have been taken and stamped into every
  /// member inspection. A completed visit no longer accepts members.
  final DateTime? completedAt;

  /// Whether the signed-off group itself has reached the server. The
  /// members upload through their own commodity endpoints; this is the
  /// group that ties them together, and the office's record is made from
  /// it.
  final bool isUploaded;

  /// When the inspector approved the visit in Inspection Management, after
  /// it reached the server and its documents were looked over.
  final DateTime? approvedAt;

  /// Whether the server holds the current answer — approved, or taken back
  /// again (Ethan, 2026-09-24). False only after the inspector has changed
  /// it; Server Sync sends any that are still waiting.
  final bool approvalSent;

  /// The producer / supplier, asked once for the whole visit and filled in
  /// on every inspection under it (Ethan, 2026-09-24).
  final String producerName;
  const StoreVisit(
      {required this.uuid,
      required this.facilityName,
      required this.facilityAddress,
      required this.facilityPhone,
      required this.contactPerson,
      required this.contactEmail,
      required this.representative,
      required this.managerName,
      required this.managerEmail,
      required this.additionalEmail1,
      required this.additionalEmail2,
      required this.additionalEmail3,
      this.distanceTravelledKm,
      required this.inspectorUsername,
      required this.plannedEggs,
      required this.plannedPoultry,
      required this.plannedLabels,
      required this.plannedRaw,
      required this.plannedPmp,
      required this.planOrder,
      required this.isOccurrenceReport,
      required this.facilityType,
      required this.inspectionReason,
      required this.occurrenceTimeOfVisit,
      required this.occurrenceRegistrationCode,
      required this.occurrenceDescription,
      required this.managerSignaturePath,
      required this.inspectorSignaturePath,
      required this.startedAt,
      this.completedAt,
      required this.isUploaded,
      this.approvedAt,
      required this.approvalSent,
      required this.producerName});
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['uuid'] = Variable<String>(uuid);
    map['facility_name'] = Variable<String>(facilityName);
    map['facility_address'] = Variable<String>(facilityAddress);
    map['facility_phone'] = Variable<String>(facilityPhone);
    map['contact_person'] = Variable<String>(contactPerson);
    map['contact_email'] = Variable<String>(contactEmail);
    map['representative'] = Variable<String>(representative);
    map['manager_name'] = Variable<String>(managerName);
    map['manager_email'] = Variable<String>(managerEmail);
    map['additional_email1'] = Variable<String>(additionalEmail1);
    map['additional_email2'] = Variable<String>(additionalEmail2);
    map['additional_email3'] = Variable<String>(additionalEmail3);
    if (!nullToAbsent || distanceTravelledKm != null) {
      map['distance_travelled_km'] = Variable<double>(distanceTravelledKm);
    }
    map['inspector_username'] = Variable<String>(inspectorUsername);
    map['planned_eggs'] = Variable<int>(plannedEggs);
    map['planned_poultry'] = Variable<int>(plannedPoultry);
    map['planned_labels'] = Variable<int>(plannedLabels);
    map['planned_raw'] = Variable<int>(plannedRaw);
    map['planned_pmp'] = Variable<int>(plannedPmp);
    map['plan_order'] = Variable<String>(planOrder);
    map['is_occurrence_report'] = Variable<bool>(isOccurrenceReport);
    map['facility_type'] = Variable<String>(facilityType);
    map['inspection_reason'] = Variable<String>(inspectionReason);
    map['occurrence_time_of_visit'] = Variable<String>(occurrenceTimeOfVisit);
    map['occurrence_registration_code'] =
        Variable<String>(occurrenceRegistrationCode);
    map['occurrence_description'] = Variable<String>(occurrenceDescription);
    map['manager_signature_path'] = Variable<String>(managerSignaturePath);
    map['inspector_signature_path'] = Variable<String>(inspectorSignaturePath);
    map['started_at'] = Variable<DateTime>(startedAt);
    if (!nullToAbsent || completedAt != null) {
      map['completed_at'] = Variable<DateTime>(completedAt);
    }
    map['is_uploaded'] = Variable<bool>(isUploaded);
    if (!nullToAbsent || approvedAt != null) {
      map['approved_at'] = Variable<DateTime>(approvedAt);
    }
    map['approval_sent'] = Variable<bool>(approvalSent);
    map['producer_name'] = Variable<String>(producerName);
    return map;
  }

  StoreVisitsCompanion toCompanion(bool nullToAbsent) {
    return StoreVisitsCompanion(
      uuid: Value(uuid),
      facilityName: Value(facilityName),
      facilityAddress: Value(facilityAddress),
      facilityPhone: Value(facilityPhone),
      contactPerson: Value(contactPerson),
      contactEmail: Value(contactEmail),
      representative: Value(representative),
      managerName: Value(managerName),
      managerEmail: Value(managerEmail),
      additionalEmail1: Value(additionalEmail1),
      additionalEmail2: Value(additionalEmail2),
      additionalEmail3: Value(additionalEmail3),
      distanceTravelledKm: distanceTravelledKm == null && nullToAbsent
          ? const Value.absent()
          : Value(distanceTravelledKm),
      inspectorUsername: Value(inspectorUsername),
      plannedEggs: Value(plannedEggs),
      plannedPoultry: Value(plannedPoultry),
      plannedLabels: Value(plannedLabels),
      plannedRaw: Value(plannedRaw),
      plannedPmp: Value(plannedPmp),
      planOrder: Value(planOrder),
      isOccurrenceReport: Value(isOccurrenceReport),
      facilityType: Value(facilityType),
      inspectionReason: Value(inspectionReason),
      occurrenceTimeOfVisit: Value(occurrenceTimeOfVisit),
      occurrenceRegistrationCode: Value(occurrenceRegistrationCode),
      occurrenceDescription: Value(occurrenceDescription),
      managerSignaturePath: Value(managerSignaturePath),
      inspectorSignaturePath: Value(inspectorSignaturePath),
      startedAt: Value(startedAt),
      completedAt: completedAt == null && nullToAbsent
          ? const Value.absent()
          : Value(completedAt),
      isUploaded: Value(isUploaded),
      approvedAt: approvedAt == null && nullToAbsent
          ? const Value.absent()
          : Value(approvedAt),
      approvalSent: Value(approvalSent),
      producerName: Value(producerName),
    );
  }

