class InvoiceRequest extends DataClass implements Insertable<InvoiceRequest> {
  /// The grouped inspection this request bills for.
  final String visitUuid;
  final String inspectorName;
  final String siteVisited;
  final String siteManager;
  final String productName;
  final DateTime dateOfVisit;

  /// "Inspection Time Started/Ended" — HH:mm as typed, because that is what
  /// goes on the form and what the office reconciles against.
  final String timeStarted;
  final String timeEnded;

  /// The form's tick boxes. Derived from what the visit actually holds, and
  /// still editable: an inspector may bill differently from what was
  /// captured, and the form is the billing document.
  final bool pmpTicked;
  final bool rawRmpTicked;
  final bool eggsTicked;
  final bool poultryTicked;
  final bool sampleTakingTicked;

  /// Hours claimed at each rate, and the distance travelled.
  final double normalHours;
  final double overtimeHours;
  final double sundayHours;
  final double kilometres;

  /// Laboratory tests sent — Processed Meat Products.
  final int pmpFatTests;
  final int pmpProteinTests;
  final int pmpCalciumTests;
  final int pmpPhysicalTests;

  /// Laboratory tests sent — Certain Raw Processed Meat Products.
  final int rawFatTests;
  final int rawProteinTests;
  final int rawSoyaTests;
  final int rawStarchTests;
  final int rawDnaTests;
  final int rawCalciumTests;

  /// What the totals came to when the form was completed, excluding VAT.
  final double inspectionTotal;
  final double pmpLabTotal;
  final double rawLabTotal;
  final double grandTotal;

  /// The two signatures the form carries. The grouped inspection already
  /// took both at sign-off, so these are copies of those images rather than
  /// a second act of signing.
  final String managerSignaturePath;
  final String inspectorSignaturePath;
  final DateTime? signedAt;

  /// Where the rendered PDF was written, so it can be opened or shared
  /// again without re-rendering.
  final String pdfPath;
  final DateTime updatedAt;
  const InvoiceRequest(
      {required this.visitUuid,
      required this.inspectorName,
      required this.siteVisited,
      required this.siteManager,
      required this.productName,
      required this.dateOfVisit,
      required this.timeStarted,
      required this.timeEnded,
      required this.pmpTicked,
      required this.rawRmpTicked,
      required this.eggsTicked,
      required this.poultryTicked,
      required this.sampleTakingTicked,
      required this.normalHours,
      required this.overtimeHours,
      required this.sundayHours,
      required this.kilometres,
      required this.pmpFatTests,
      required this.pmpProteinTests,
      required this.pmpCalciumTests,
      required this.pmpPhysicalTests,
      required this.rawFatTests,
      required this.rawProteinTests,
      required this.rawSoyaTests,
      required this.rawStarchTests,
      required this.rawDnaTests,
      required this.rawCalciumTests,
      required this.inspectionTotal,
      required this.pmpLabTotal,
