class PoultryQuidSample extends DataClass
    implements Insertable<PoultryQuidSample> {
  final int id;
  final String inspectionUuid;
  final String carcassNumber;
  final String injectorNumber;

  /// Water chilling: the carcass off the line, what it weighed after, and
  /// what it picked up between the two.
  final String initialMassG;
  final String afterMassG;
  final String finalMassG;
  final String pickupPercent;

  /// Injector processing, which the original weighs separately from the
  /// chilling: the carcass onto the injector, off it, the gain between, and
  /// that gain as a rate.
  final String beforeMassG;

  /// The carcass off the injector. Its own column: [afterMassG] is the
  /// chilling reading and writing both into one silently destroyed
  /// whichever was weighed first.
  final String injectorAfterMassG;
  final String gainG;
  final String injectorRatePercent;

  /// Determination of QUID for this carcass.
  ///
  /// The original weighs it per carcass, not once per consignment: the
  /// initial mass is the carcass's own chilling weight and the final mass is
  /// weighed after processing, so QUID is (final - initial) / final. One pair
  /// of masses for the whole inspection cannot be read back against the
  /// injector that produced it.
  final String quidFinalMassG;
  final String quidGainG;
  final String quidPercent;

  /// Which injector on the set-up list processed this carcass, by position.
  /// Empty while it has not been assigned.
  final String assignedInjector;

  /// Which round of weighing this carcass belongs to: 1, or 2 when the
  /// determination had to be repeated. Only the last round is judged.
  final int iteration;
  const PoultryQuidSample(
      {required this.id,
      required this.inspectionUuid,
      required this.carcassNumber,
      required this.injectorNumber,
      required this.initialMassG,
      required this.afterMassG,
      required this.finalMassG,
      required this.pickupPercent,
      required this.beforeMassG,
      required this.injectorAfterMassG,
      required this.gainG,
      required this.injectorRatePercent,
      required this.quidFinalMassG,
      required this.quidGainG,
      required this.quidPercent,
      required this.assignedInjector,
      required this.iteration});
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<int>(id);
    map['inspection_uuid'] = Variable<String>(inspectionUuid);
    map['carcass_number'] = Variable<String>(carcassNumber);
    map['injector_number'] = Variable<String>(injectorNumber);
    map['initial_mass_g'] = Variable<String>(initialMassG);
    map['after_mass_g'] = Variable<String>(afterMassG);
    map['final_mass_g'] = Variable<String>(finalMassG);
    map['pickup_percent'] = Variable<String>(pickupPercent);
    map['before_mass_g'] = Variable<String>(beforeMassG);
    map['injector_after_mass_g'] = Variable<String>(injectorAfterMassG);
    map['gain_g'] = Variable<String>(gainG);
    map['injector_rate_percent'] = Variable<String>(injectorRatePercent);
    map['quid_final_mass_g'] = Variable<String>(quidFinalMassG);
    map['quid_gain_g'] = Variable<String>(quidGainG);
    map['quid_percent'] = Variable<String>(quidPercent);
    map['assigned_injector'] = Variable<String>(assignedInjector);
    map['iteration'] = Variable<int>(iteration);
    return map;
  }

