class RawRmpDirection extends DataClass implements Insertable<RawRmpDirection> {
  final String clientUuid;
  final String inspectorUsername;
  final String status;
  final DateTime issuedAt;
  final String facilityName;
  final String clientName;
  final String clientEmail;
  final int? remarkTypeId;
  final String remarks;
  final String comments;
  final String actionTaken;
  final String nonConformanceIds;

  /// The number the direction is known by, generated when it is raised.
  ///
  /// `client / inspector id / date / nn`, where nn counts the
  /// directions this inspector has raised today — the original's
  /// `UniqueReferenceNumber`. The office quotes it back, so it is written
  /// once and never renumbered when the direction is refreshed.
  final String referenceNumber;

  /// The deadline on the notice. It is captured on the inspection and
  /// copied here, because the notice is what the client is served with and
  /// the office reads the date off the direction.
  final DateTime? correctByDate;

  /// The inspection this direction was raised from. The original creates the
  /// direction inside the inspection save and links it back; the summary's
  /// photographs are the inspection's photographs.
  final String? sourceInspectionUuid;
  final String newFacilityName;
  final String producerName;
  final String newProducerName;
  final String batchNumber;
  final String manufacturedPackedDate;
  final String primarySampleSize;
  final String restrictedParticularIds;
  final double? latitude;
  final double? longitude;
  final bool isUploaded;
  final DateTime updatedAt;
  const RawRmpDirection(
      {required this.clientUuid,
      required this.inspectorUsername,
      required this.status,
      required this.issuedAt,
      required this.facilityName,
      required this.clientName,
      required this.clientEmail,
      this.remarkTypeId,
      required this.remarks,
      required this.comments,
      required this.actionTaken,
      required this.nonConformanceIds,
      required this.referenceNumber,
      this.correctByDate,
      this.sourceInspectionUuid,
      required this.newFacilityName,
      required this.producerName,
      required this.newProducerName,
      required this.batchNumber,
      required this.manufacturedPackedDate,
      required this.primarySampleSize,
      required this.restrictedParticularIds,
      this.latitude,
      this.longitude,
      required this.isUploaded,
      required this.updatedAt});
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['client_uuid'] = Variable<String>(clientUuid);
    map['inspector_username'] = Variable<String>(inspectorUsername);
    map['status'] = Variable<String>(status);
    map['issued_at'] = Variable<DateTime>(issuedAt);
    map['facility_name'] = Variable<String>(facilityName);
    map['client_name'] = Variable<String>(clientName);
    map['client_email'] = Variable<String>(clientEmail);
    if (!nullToAbsent || remarkTypeId != null) {
      map['remark_type_id'] = Variable<int>(remarkTypeId);
    }
    map['remarks'] = Variable<String>(remarks);
    map['comments'] = Variable<String>(comments);
    map['action_taken'] = Variable<String>(actionTaken);
    map['non_conformance_ids'] = Variable<String>(nonConformanceIds);
    map['reference_number'] = Variable<String>(referenceNumber);
    if (!nullToAbsent || correctByDate != null) {
      map['correct_by_date'] = Variable<DateTime>(correctByDate);
    }
    if (!nullToAbsent || sourceInspectionUuid != null) {
      map['source_inspection_uuid'] = Variable<String>(sourceInspectionUuid);
    }
    map['new_facility_name'] = Variable<String>(newFacilityName);
    map['producer_name'] = Variable<String>(producerName);
    map['new_producer_name'] = Variable<String>(newProducerName);
    map['batch_number'] = Variable<String>(batchNumber);
    map['manufactured_packed_date'] = Variable<String>(manufacturedPackedDate);
    map['primary_sample_size'] = Variable<String>(primarySampleSize);
    map['restricted_particular_ids'] =
        Variable<String>(restrictedParticularIds);
    if (!nullToAbsent || latitude != null) {
      map['latitude'] = Variable<double>(latitude);
    }
    if (!nullToAbsent || longitude != null) {
      map['longitude'] = Variable<double>(longitude);
    }
    map['is_uploaded'] = Variable<bool>(isUploaded);
    map['updated_at'] = Variable<DateTime>(updatedAt);
    return map;
  }

  RawRmpDirectionsCompanion toCompanion(bool nullToAbsent) {
    return RawRmpDirectionsCompanion(
      clientUuid: Value(clientUuid),
      inspectorUsername: Value(inspectorUsername),
      status: Value(status),
      issuedAt: Value(issuedAt),
      facilityName: Value(facilityName),
      clientName: Value(clientName),
      clientEmail: Value(clientEmail),
      remarkTypeId: remarkTypeId == null && nullToAbsent
          ? const Value.absent()
          : Value(remarkTypeId),
      remarks: Value(remarks),
      comments: Value(comments),
      actionTaken: Value(actionTaken),
      nonConformanceIds: Value(nonConformanceIds),
      referenceNumber: Value(referenceNumber),
      correctByDate: correctByDate == null && nullToAbsent
